     "**ហេតុអ្វីបានជា ASS របស់ខ្ញុំមិនអាចនាំចេញបាន?** QC នាំចេញតែ SRT និង VTT ប៉ុណ្ណោះ; ASS ចូលទៅក្នុង ប៉ុន្តែមិនចេញមកក្រៅទេ។ ដើម្បីរក្សាបែបផែន ASS សូមគិតឱ្យបានច្បាស់លាស់នៅ [[កម្មវិធីបម្លែងទម្រង់|/convert.html]] មុនសិន។",
